mapper.sql:
 FROM user_realname_verification v JOIN sys_user u ON u.id=v.user_id WHERE 1=1 
AND (v.verification_status)=#{verificationFilter.status}
AND v.submitted_at >=#{verificationFilter.from}
AND v.submitted_at <#{verificationFilter.to}


    AND (v.user_id=#{verificationFilter.keyword} OR CONCAT('RV',v.id)=#{verificationFilter.keyword})
    AND (u.nickname LIKE #{verificationFilter.keyword} ESCAPE '!' )
